def render(s,p):
 v,tr=s.tessellate(.3);v=np.array([[x.x,x.y,x.z] for x in v]);fig=plt.figure(figsize=(6.8,3.5));ax=fig.add_axes([0,0,1,1],projection='3d');ax.add_collection3d(Poly3DCollection(v[np.array(tr)],facecolors='#b8d0df',edgecolors='#465c72',linewidths=.13));ax.auto_scale_xyz(*v.T);ax.set_box_aspect(np.maximum(np.ptp(v,axis=0),1),zoom=1.25);ax.view_init(28,-55);ax.set_axis_off();fig.savefig(p,dpi=180);plt.close(fig)
