fig=plt.figure(figsize=(7,3.6));ax=fig.add_axes([.02,.02,.8,.93],projection='3d');p=rr.mesh.nodes[mask];sc=ax.scatter(*p.T,c=vm[mask],cmap='turbo',s=2,rasterized=True);ax.set_box_aspect(np.maximum(np.ptp(rr.mesh.nodes,axis=0),1));ax.view_init(28,-55);ax.set_axis_off();fig.colorbar(sc,ax=ax,shrink=.7,label='Stored averaged corner-node VM [MPa]');fig.savefig(T/'cover-original-FEM-stress-points.png',dpi=180);plt.close(fig);deck=(rst.parent/'ds.dat').read_text(errors='replace');bc=re.findall(r'^CMBLOCK,([^\n]+)',deck,re.M)
